#!/usr/bin/env python3
"""Write ``AutoGenerated/geometry_to_physics.json`` (D-025).

Walks the declarative chain in ``simulations.PM.paper.physics_chain`` and, for
every step, reads the value from parameters.json, the status from the registry
(the parameter's status, else the formula category), the experiment and pull
from validation_report.json, and the formula text from formulas.json.  The
closed-geometry steps read closed_geometry.certificate and the G2 closure
report.  Nothing is typed by hand: an input that cannot be found becomes
``"OPEN"`` with a reason in ``why``.

Run: ``python -m metaphysica.generators.generate_geometry_to_physics``
"""
from __future__ import annotations

import json
import sys
from collections import Counter
from typing import Any, Dict, List, Optional

from metaphysica.generators._common import autogen_dir, write_json_stable
from metaphysica.simulations.PM.paper.physics_chain import CHAIN, STAGES, Step

OPEN = "OPEN"
AMBER = {"FITTED", "CALIBRATED", "FITTED_COMPOSITE", "RETRODICTED_VARIANT"}
RED = {"FALSIFIED", "FAILING"}
OUTPUT_NAME = "geometry_to_physics.json"


def _load(name: str) -> Any:
    path = autogen_dir() / name
    if not path.is_file():
        raise FileNotFoundError("%s is missing: run the build first" % path)
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def _tone(status: str, verdict: Optional[str]) -> str:
    if status == OPEN:
        return "open"
    if verdict == "FAIL" or status in RED:
        return "fail"
    if status in AMBER:
        return "fitted"
    return "ok"


def _experiment(row: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    if not row:
        return {"verdict": "NO_TEST",
                "why": "no validation_report row for this quantity"}
    return {"value": row.get("experimental_value"),
            "uncertainty": row.get("experimental_uncertainty"),
            "source": row.get("experimental_source"),
            "pull": row.get("sigma"), "verdict": row.get("verdict")}


def _formula_block(formula: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    if not formula:
        return {"latex": OPEN, "plain_text": OPEN, "category": OPEN}
    return {"latex": formula.get("latex", OPEN),
            "plain_text": formula.get("plain_text", OPEN),
            "category": formula.get("category", OPEN),
            "label": formula.get("label", "")}


def _param_fields(step: Step, params: Dict[str, Any],
                  formula: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """value/status/value_source for a step that reads parameters.json."""
    why: Dict[str, str] = {}
    entry = params.get(step.param_path)
    value, status = OPEN, OPEN
    if not isinstance(entry, dict) or "value" not in entry:
        why["value"] = "param_path %r is not in parameters.json" % step.param_path
        if formula:
            status = formula.get("category", OPEN)
    else:
        value = entry["value"]
        status = entry.get("status") or (formula or {}).get("category", OPEN)
    if status == OPEN:
        why["status"] = "neither the parameter nor a formula carries a status"
    return {"value": value, "status": status, "value_source": "parameters.json",
            "why": why}


def _theorem_fields(step: Step, theorems: Dict[str, Dict[str, Any]],
                    closure: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    src = "closed_geometry.certificate"
    if step.theorem_id == "closure_report":
        src = "g2_closure.closure_report"
        if not closure:
            return {"value": OPEN, "status": OPEN, "value_source": src,
                    "why": {"value": "closure_report unavailable"}}
        ok = closure.get("verdict") == "CLOSED_BY_THEOREM"
        return {"value": closure.get("verdict"),
                "status": "THEOREM" if ok else "FAILING",
                "value_source": src, "why": {}}
    row = theorems.get(step.theorem_id)
    if row is None:
        return {"value": OPEN, "status": OPEN, "value_source": src,
                "why": {"value": "theorem %r not in the certificate" % step.theorem_id}}
    return {"value": bool(row.get("holds")),
            "status": "THEOREM" if row.get("holds") else "FAILING",
            "value_source": src, "why": {}}


def _theorem_formula(step: Step, theorems: Dict[str, Dict[str, Any]],
                     closure: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    if step.theorem_id == "closure_report":
        concl = (closure or {}).get("conclusions") or []
        text = "; ".join(str(c.get("claim", "")) for c in concl)
        return {"latex": "", "plain_text": text or OPEN, "category": "THEOREM",
                "label": "(CG.13)"}
    row = theorems.get(step.theorem_id)
    if not row:
        return None
    return {"latex": "", "plain_text": row.get("statement", OPEN),
            "category": "THEOREM", "label": row.get("label", "")}


def build_step(step: Step, ctx: Dict[str, Any], order: int) -> Dict[str, Any]:
    """One output record. ``ctx`` carries the loaded artifacts."""
    formula = ctx["formulas"].get(step.formula_id) if step.formula_id else None
    if step.theorem_id:
        fields = _theorem_fields(step, ctx["theorems"], ctx["closure"])
        formula = _theorem_formula(step, ctx["theorems"], ctx["closure"])
    else:
        fields = _param_fields(step, ctx["params"], formula)
    row = ctx["validations"].get(step.param_path) if step.param_path else None
    exp = _experiment(row)
    if step.formula_id and formula is None:
        fields["why"]["formula"] = "formula_id %r not in formulas.json" % step.formula_id
    fig = ctx["figures"].get(step.figure) if step.figure else None
    if step.figure and fig is None:
        fields["why"]["figure"] = "figure %r not produced" % step.figure
    return {"id": step.id, "order": order, "stage": step.stage,
            "geometric_input": step.geometric_input, "operation": step.operation,
            "output_symbol": step.output_symbol, "param_path": step.param_path,
            "formula_id": step.formula_id, "theorem_id": step.theorem_id,
            "section_id": step.section_id,
            "section_href": ("paper.html#section-%s" % step.section_id
                             if step.section_id else ""),
            "formula": _formula_block(formula), "experiment": exp,
            "tone": _tone(fields["status"], exp.get("verdict")),
            "figure": step.figure, "figure_svg": (fig or {}).get("svg", ""),
            "figure_caption": (fig or {}).get("caption", ""), **fields}


def summarise(steps: List[Dict[str, Any]]) -> Dict[str, Any]:
    return {"steps": len(steps),
            "by_status": dict(Counter(s["status"] for s in steps)),
            "by_tone": dict(Counter(s["tone"] for s in steps)),
            "by_verdict": dict(Counter(s["experiment"].get("verdict", "NO_TEST")
                                       for s in steps)),
            "open_fields": sum(len(s["why"]) for s in steps)}


def build_walkthrough(ctx: Dict[str, Any], chain=CHAIN) -> Dict[str, Any]:
    steps = [build_step(s, ctx, i + 1) for i, s in enumerate(chain)]
    return {"schema_version": 1, "decision": "D-025",
            "note": ("Every value, status and experiment is read from engine "
                     "artifacts. OPEN marks an input that could not be found."),
            "stages": [{"id": i, "label": label} for i, label in STAGES],
            "summary": summarise(steps), "steps": steps}


def _theorems() -> Dict[str, Dict[str, Any]]:
    from metaphysica.simulations.PM.geometry.closed_geometry.certificate import certificate
    return {r["id"]: r for r in certificate()}


def _closure() -> Optional[Dict[str, Any]]:
    from metaphysica.simulations.PM.geometry.g2_closure import closure_report
    return closure_report()


def _figures() -> Dict[str, Dict[str, str]]:
    from metaphysica.simulations.PM.geometry.figures import (
        geometry_figures, proof_figures)
    return {f["id"].replace("-", "_"): f
            for f in geometry_figures() + proof_figures()}


def load_context() -> Dict[str, Any]:
    params = _load("parameters.json")["parameters"]      # fail early
    formulas = _load("formulas.json")["formulas"]
    rows = _load("validation_report.json")["validations"]
    return {"params": params, "formulas": formulas,
            "validations": {r["path"]: r for r in rows},
            "theorems": _theorems(), "closure": _closure(),
            "figures": _figures()}


def main() -> int:
    doc = build_walkthrough(load_context())
    write_json_stable(autogen_dir() / OUTPUT_NAME, doc)
    s = doc["summary"]
    print("geometry_to_physics: %d steps, status %s, open fields %d"
          % (s["steps"], s["by_status"], s["open_fields"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
